/**
 * FFI-friendly decrypted chat message.
 */
public struct MessageInfo: Equatable, Hashable {
    public var idHex: String
    public var senderNpub: String
    public var content: String
    public var createdAtSecs: UInt64
    /**
     * True when the local identity sent it.
     */
    public var mine: Bool
    /**
     * Local delivery state: received, pending, sent, or failed.
     */
    public var deliveryState: String
    /**
     * Encrypted media attachments (Marmot MIP-04), empty for a plain text message.
     */
    public var media: [MediaInfo]
    /**
     * Sticker reference if this message is a sticker send (nil for text/media).
     */
    public var stickerRef: StickerRefInfo?
    /**
     * Precomputed content classification (pay/call control vs plain text).
     */
    public var classification: MessageClassInfo
    /**
     * NIP-C7 reply pointer. `content` is the display body (nevent already stripped).
     */
    public var reply: ReplyRefInfo?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(idHex: String, senderNpub: String, content: String, createdAtSecs: UInt64,
        /**
         * True when the local identity sent it.
         */mine: Bool,
        /**
         * Local delivery state: received, pending, sent, or failed.
         */deliveryState: String,
        /**
         * Encrypted media attachments (Marmot MIP-04), empty for a plain text message.
         */media: [MediaInfo],
        /**
         * Sticker reference if this message is a sticker send (nil for text/media).
         */stickerRef: StickerRefInfo?,
        /**
         * Precomputed content classification (pay/call control vs plain text).
         */classification: MessageClassInfo,
        /**
         * NIP-C7 reply pointer. `content` is the display body (nevent already stripped).
         */reply: ReplyRefInfo?) {
        self.idHex = idHex
        self.senderNpub = senderNpub
